#!/usr/bin/env node
/**
 * Freezes expected engine/layout/lifecycle values from the reference
 * TypeScript implementation. Run after `generate.mjs` and `vp pack` for
 * sdk/core. The resulting JSON is committed and never regenerated by tests.
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { OrbitEngine, computeLayout } from "../../sdk/core/dist/index.js";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");

function readJson(file) {
  return JSON.parse(fs.readFileSync(file, "utf8"));
}

function writeJson(file, value) {
  fs.writeFileSync(file, JSON.stringify(value, null, 2) + "\n");
}

function applyEvent(engine, event) {
  switch (event.type) {
    case "setAngle":
      engine.setAngle(event.angle, event.immediate === true);
      break;
    case "rotateBy":
      engine.rotateBy(event.deg);
      break;
    case "pointerDown":
      engine.pointerDown(event.x, event.y, event.timeMs);
      break;
    case "pointerMove":
      engine.pointerMove(event.x, event.y, event.timeMs);
      break;
    case "pointerUp":
      engine.pointerUp(event.timeMs);
      break;
    case "gyro":
      engine.gyro({ heading: event.heading, timeMs: event.timeMs });
      break;
    case "advance":
      engine.advance(event.dtMs);
      break;
    case "pause":
      engine.pause();
      break;
    case "resume":
      engine.resume();
      break;
    case "reset":
      engine.reset(event.angle === undefined ? 0 : event.angle, event.immediate !== false);
      break;
    case "load":
      engine.load(event.bundle);
      break;
    case "unload":
      engine.unload();
      break;
    case "destroy":
      engine.destroy();
      break;
    case "setConfig":
      engine.setConfig(event.config || {});
      break;
    default:
      throw new Error(`unknown event type: ${event.type}`);
  }
}

function freezeEngineDir(dir) {
  for (const name of fs.readdirSync(dir)) {
    if (!name.endsWith(".json")) continue;
    const file = path.join(dir, name);
    const item = readJson(file);
    const engine = new OrbitEngine(item.bundle, { config: item.config || {} });
    for (const event of item.events || []) applyEvent(engine, event);
    item.expect = engine.getSnapshot();
    writeJson(file, item);
  }
}

freezeEngineDir(path.join(ROOT, "conformance/engine"));
freezeEngineDir(path.join(ROOT, "conformance/lifecycle"));

const layoutDir = path.join(ROOT, "conformance/layout");
for (const name of fs.readdirSync(layoutDir)) {
  if (!name.endsWith(".json")) continue;
  const file = path.join(layoutDir, name);
  const item = readJson(file);
  const { name: _name, kind: _kind, expect: _expect, ...input } = item;
  item.expect = computeLayout(input);
  writeJson(file, item);
}

console.log("frozen expected values for engine, layout and lifecycle cases");
